        layoutWrap.append(main,aside);
        if(upperLeft) main.appendChild(upperLeft);
        if(lower){lower.classList.add('local-config-main','local-echo-wide');layoutWrap.appendChild(lower);}
        if(upperRight) aside.appendChild(upperRight);
        if(upper) upper.style.display='none';
        activeCol.appendChild(layoutWrap);
