  function enhanceStats(){
    document.querySelectorAll('.local-active .echo-main-fields').forEach(function(fields){
      if(fields.querySelector('.local-stat-trigger')) return;
      var select=fields.querySelector('[data-echo-main1]');if(!select)return;
      var element=fields.querySelector('[data-echo-main-element]');
      var trigger=document.createElement('button');trigger.type='button';trigger.className='local-stat-trigger';
      trigger.textContent=element?element.value:select.selectedOptions[0].textContent;
      trigger.onclick=function(){
        var old=document.querySelector('.local-stat-popup');if(old)old.remove();
        var popup=document.createElement('div');popup.className='local-stat-popup';popup.setAttribute('role','dialog');popup.setAttribute('aria-label','选择主词条');
        function item(label,action){var b=document.createElement('button');b.type='button';b.textContent=label;b.onclick=function(e){e.stopPropagation();action();};popup.appendChild(b);}
        function change(value,elValue){
          var member=select.closest('[data-setup-member]').dataset.setupMember,slot=select.dataset.echoMain1;
          popup.remove();select.value=value;select.dispatchEvent(new Event('change',{bubbles:true}));
          if(elValue){var fresh=document.querySelector('[data-setup-member="'+member+'"] [data-echo-main-element="'+slot+'"]');if(fresh){fresh.value=elValue;fresh.dispatchEvent(new Event('change',{bubbles:true}));}}
        }
        function categories(){popup.replaceChildren();Array.from(select.options).forEach(function(o){item(o.textContent+(o.value==='main_element_dmg'?' ›':''),function(){if(o.value==='main_element_dmg'){popup.replaceChildren();item('‹ 返回主词条',categories);['冷凝','热熔','导电','气动','衍射','湮灭'].forEach(function(v){item(v,function(){change(o.value,v);});});}else change(o.value);});});}
        categories();document.body.appendChild(popup);var r=trigger.getBoundingClientRect();popup.style.left=Math.min(r.left,innerWidth-244)+'px';popup.style.top=Math.max(8,Math.min(r.bottom+5,innerHeight-popup.offsetHeight-8))+'px';popup.querySelector('button').focus();
      };
      fields.insertBefore(trigger,fields.firstChild);
    });
  }
  document.addEventListener('click',function(e){var p=document.querySelector('.local-stat-popup');if(p&&!p.contains(e.target)&&!e.target.closest('.local-stat-trigger'))p.remove();});
  document.addEventListener('keydown',function(e){if(e.key==='Escape'){var p=document.querySelector('.local-stat-popup');if(p)p.remove();}});
