          var needs=!setup.querySelector('.local-team-strip') || !setup.querySelector('.local-config-hero') || !setup.querySelector('.local-config-layout') || !setup.querySelector('.setup-member-col.local-active') || !setup.querySelector('.setup-member-col.local-active .local-config-main > [data-wc-chain-compact]');
          if(cols.length && needs) install();
