/* Static watermark from each slot's actual displayed echo artwork. */
(()=>{
 function sync(){
  document.querySelectorAll('.local-echo-wide .build-slot-card').forEach(card=>{
   const image=card.querySelector('.build-slot-visual img');
   const source=image?.getAttribute('src');
   let layer=card.querySelector('.local-echo-watermark');
   if(!source){layer?.remove();return;}
   if(!layer){layer=document.createElement('span');layer.className='local-echo-watermark';layer.setAttribute('aria-hidden','true');card.append(layer);}
   const value='url('+JSON.stringify(source)+')';
   if(layer.style.backgroundImage!==value)layer.style.backgroundImage=value;
  });
 }
 let queued=false;
 new MutationObserver(()=>{if(!queued){queued=true;queueMicrotask(()=>{queued=false;sync();});}}).observe(document.body,{childList:true,subtree:true,attributes:true,attributeFilter:['src']});
 sync();
})();

