/* SpotlightCard's pointer positioning, on existing interactive cards. */
(()=>{
 const selector='#workspaceLayout.phase-setup .build-panel-stat-card, #workspaceLayout.phase-setup .setup-sec-weapon [data-build-open-modal="weapon"], #workspaceLayout.phase-setup .setup-sec-weapon .build-set-pick';
 document.addEventListener('pointermove',e=>{
  const card=e.target.closest(selector);if(!card)return;
  const rect=card.getBoundingClientRect();
  card.style.setProperty('--mouse-x',`${e.clientX-rect.left}px`);
  card.style.setProperty('--mouse-y',`${e.clientY-rect.top}px`);
 });
})();

